// Number predicates and Math functions over float literals.
console.log(Number.isInteger(5.0), Number.isInteger(5.5), Number.isInteger(-0.0));
console.log(Number.isSafeInteger(5.0), Number.isFinite(5.0), Number.isNaN(5.0));
console.log(Math.floor(5.5), Math.trunc(-2.7), Math.abs(-3.0), Math.sign(-2.0), Math.round(2.5));
